import{_ as t,o as n,c as a,a2 as i}from"./chunks/framework.CtQGab4e.js";const c=JSON.parse('{"title":"Importeren in Label-wise","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/label-wise.md","filePath":"plattegrond/label-wise.md"}'),o={name:"plattegrond/label-wise.md"};function l(r,e,s,d,p,h){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="importeren-in-label-wise" tabindex="-1">Importeren in Label-wise <a class="header-anchor" href="#importeren-in-label-wise" aria-label="Permalink to &quot;Importeren in Label-wise&quot;">​</a></h1><p>Van het 3D-model maak je een importbestand voor Label-wise: de rekenzones met hun constructies, oppervlaktes, oriëntatie en helling, en de kozijnen als deelvlak.</p><h2 id="het-bestand-maken" tabindex="-1">Het bestand maken <a class="header-anchor" href="#het-bestand-maken" aria-label="Permalink to &quot;Het bestand maken&quot;">​</a></h2><ol><li><a href="./kozijnen-koppelen.html">Koppel de kozijnen</a>.</li><li>Tik in het <a href="./3d-paneel.html">3D-paneel</a> op <strong>Exporteren</strong> en laat <strong>Label-wise</strong> aangevinkt. Je krijgt <code>Label-wise import.json</code>, eventueel samen met de andere bestanden in een zip (zie <a href="./export-3d.html#uit-het-3d-paneel">Exporteren voor 3D</a>).</li><li>Kijk in het log van het 3D-paneel: daar staat wat je in Label-wise nog moet nakijken of invullen, per zone.</li></ol><h2 id="importeren" tabindex="-1">Importeren <a class="header-anchor" href="#importeren" aria-label="Permalink to &quot;Importeren&quot;">​</a></h2><p>Tik in Label-wise in het projectenoverzicht op <strong>Importeren</strong> en sleep het bestand naar het venster.* Vul in het importvenster het <strong>bouwjaar</strong> in: zonder bouwjaar kun je niet bevestigen.</p><p class="opmerking">* Importeren in een bestaand project kan nog niet.</p><h2 id="wat-het-bestand-doet" tabindex="-1">Wat het bestand doet <a class="header-anchor" href="#wat-het-bestand-doet" aria-label="Permalink to &quot;Wat het bestand doet&quot;">​</a></h2><ul><li>Elke <a href="./installaties.html">klimatiseringszone</a> wordt een rekenzone.</li><li>Elke constructie uit het 3D-paneel wordt een hoofdvlak, met de m² inclusief je <a href="./constructies.html">correcties</a>. De kozijnen worden deelvlakken.</li><li>De helling wordt afgerond op een veelvoud van 15°, want andere hellingen kent Label-wise niet. Het log noemt elke afronding.</li><li>Elk vlak krijgt een constructie uit de bibliotheek. De Rc-waarden vul je zelf in.</li><li>Een ander <a href="./gebouw.html#gebouwdelen">gebouwdeel</a> of een afwijkende isolatie krijgt een eigen constructie, bijvoorbeeld <em>Gevel aanbouw</em> of <em>Gevel (10cm PIR)</em>. Het log noemt ze.</li></ul><div class="tip custom-block"><p class="custom-block-title">Projectnaam</p><p>De titel van je notitie wordt de naam van het project in Label-wise. Geef de notitie dus het adres als titel.</p></div>',10)])])}const b=t(o,[["render",l]]);export{c as __pageData,b as default};
